const COLORS = {"SPEAKER_00": "#e57373", "SPEAKER_01": "#64b5f6", "SPEAKER_02": "#81c784", "SPEAKER_03": "#ba68c8", "SPEAKER_04": "#ffb74d", "SPEAKER_05": "#4dd0e1"};
const DIAR_STATS = {"counts": {"SPEAKER_00": 10, "SPEAKER_01": 7, "SPEAKER_02": 2, "SPEAKER_03": 1, "SPEAKER_04": 48, "SPEAKER_05": 70}, "durs": {"SPEAKER_00": 42.6, "SPEAKER_01": 47.9, "SPEAKER_02": 7.8, "SPEAKER_03": 6.2, "SPEAKER_04": 193.5, "SPEAKER_05": 127.0}};
const TOTAL_DUR = 420.0;

function fmtTime(t) {
  const m = Math.floor(t / 60);
  const s = (t % 60).toFixed(2);
  return m + ":" + (s.padStart(5, '0'));
}
function fmtRange(s, e) { return fmtTime(s) + " → " + fmtTime(e); }
function dur(s) { return (s.end - s.start).toFixed(2) + "s"; }

// speaker stats from diarization
const statsEl = document.getElementById("speaker-stats");
const spks = Object.keys(DIAR_STATS.counts).sort();
spks.forEach(spk => {
  const c = COLORS[spk] || "#888";
  const cnt = DIAR_STATS.counts[spk];
  const d = DIAR_STATS.durs[spk];
  const div = document.createElement("div");
  div.className = "stat";
  div.innerHTML = '<div class="swatch" style="background:' + c + '"></div>' +
    '<div><strong>' + spk + '</strong><br>' + cnt + ' segs · ' + d + 's</div>';
  statsEl.appendChild(div);
});

// timeline SVG (from EXPORT segments which is what survived to final)
const svg = document.getElementById("timeline");
const W = 1200, H = 60;
SEGMENTS.forEach(s => {
  const x = (s.start / TOTAL_DUR) * W;
  const w = Math.max(1.5, ((s.end - s.start) / TOTAL_DUR) * W);
  const c = COLORS[s.speaker] || "#888";
  const r = document.createElementNS("http://www.w3.org/2000/svg", "rect");
  r.setAttribute("x", x); r.setAttribute("y", 8);
  r.setAttribute("width", w); r.setAttribute("height", H - 16);
  r.setAttribute("fill", c);
  r.setAttribute("opacity", "0.85");
  r.setAttribute("data-start", s.start);
  r.setAttribute("data-i", s._i);
  r.style.cursor = "pointer";
  r.addEventListener("click", () => jumpFull(s.start, s));
  const title = document.createElementNS("http://www.w3.org/2000/svg", "title");
  title.textContent = "#" + s.index + " " + s.speaker + " " + fmtRange(s.start, s.end) + "\n" + (s.text || "");
  r.appendChild(title);
  svg.appendChild(r);
});
// time tick labels
[0, 60, 120, 180, 240, 300, 360, 420].forEach(t => {
  const x = (t / TOTAL_DUR) * W;
  const txt = document.createElementNS("http://www.w3.org/2000/svg", "text");
  txt.setAttribute("x", x); txt.setAttribute("y", 56);
  txt.setAttribute("font-size", "8"); txt.setAttribute("fill", "#999");
  txt.setAttribute("font-family", "monospace");
  txt.textContent = t + "s";
  svg.appendChild(txt);
});

// player jump
const playerFull = document.getElementById("player-full");
const nowLabel = document.getElementById("now-label");
function jumpFull(t, seg) {
  playerFull.currentTime = t;
  playerFull.play();
  if (seg) {
    nowLabel.textContent = "#" + seg.index + " " + seg.speaker + " · " + fmtRange(seg.start, seg.end);
  }
}

// speaker filter options
const fspk = document.getElementById("filter-speaker");
spks.forEach(s => {
  const o = document.createElement("option");
  o.value = s; o.textContent = s + " (" + DIAR_STATS.counts[s] + ")";
  fspk.appendChild(o);
});

// render segments
const tbody = document.getElementById("segments");
const searchEl = document.getElementById("search");
const fflag = document.getElementById("filter-flag");
const vcount = document.getElementById("visible-count");

function flagsHTML(s) {
  const out = [];
  if (s.sepreformer) out.push('<span class="flag flag-sepreformer">SepReformer</span>');
  if (s.is_separated) out.push('<span class="flag flag-separated">separated</span>');
  if (s.demucs) out.push('<span class="flag flag-demucs">demucs</span>');
  if ((s.end - s.start) < 1.0) out.push('<span class="flag flag-short">&lt;1s</span>');
  if (s.asr_quality_actions && s.asr_quality_actions.length)
    out.push('<span class="flag flag-qa">qg:' + s.asr_quality_actions.length + '</span>');
  if (s.asr_quality_source && s.asr_quality_source !== 'rover')
    out.push('<span class="flag">' + s.asr_quality_source + '</span>');
  return out.join(" ");
}

function altsHTML(s) {
  // show alt transcripts only if they differ from final
  const f = (s.text || "").trim();
  const lines = [];
  const norm = (t) => (t || "").trim().toLowerCase().replace(/[.,!?]/g, "");
  if (s.text_whisper && norm(s.text_whisper) !== norm(f))
    lines.push('<div class="alt-line"><span class="src">w</span>: ' + escapeHTML(s.text_whisper) + '</div>');
  if (s.text_phowhisper && norm(s.text_phowhisper) !== norm(f))
    lines.push('<div class="alt-line"><span class="src">p</span>: ' + escapeHTML(s.text_phowhisper) + '</div>');
  if (s.text_chunkformer && norm(s.text_chunkformer) !== norm(f))
    lines.push('<div class="alt-line"><span class="src">c</span>: ' + escapeHTML(s.text_chunkformer) + '</div>');
  return lines.join("");
}

function escapeHTML(t) {
  return (t || "").replace(/[&<>"']/g, ch => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[ch]));
}

function detailsHTML(s) {
  const rows = [];
  rows.push('<div class="alt-grid">');
  rows.push('<div class="lbl">FINAL</div><div>' + escapeHTML(s.text) + '</div>');
  rows.push('<div class="lbl">Whisper</div><div>' + escapeHTML(s.text_whisper) + '</div>');
  rows.push('<div class="lbl">PhoWhisper</div><div>' + escapeHTML(s.text_phowhisper) + '</div>');
  rows.push('<div class="lbl">ChunkFormer</div><div>' + escapeHTML(s.text_chunkformer) + '</div>');
  rows.push('</div>');
  rows.push('<div><span class="k">quality src:</span> ' + (s.asr_quality_source || '—') + '</div>');
  if (s.asr_quality_actions && s.asr_quality_actions.length) {
    rows.push('<div><span class="k">actions:</span> ' + s.asr_quality_actions.join(", ") + '</div>');
  }
  rows.push('<div><span class="k">pad:</span> before ' + s.asr_context_pad_before + 's · after ' + s.asr_context_pad_after + 's</div>');
  if (s.source_index !== s.index || s.source_start !== s.start) {
    rows.push('<div><span class="k">source:</span> #' + s.source_index + ' ' + fmtRange(s.source_start, s.source_end) + '</div>');
  }
  if (s._sep_files && s._sep_files.length) {
    rows.push('<div><span class="k">separated wavs:</span></div>');
    s._sep_files.forEach(fn => {
      rows.push('<div style="margin-left:8px"><audio class="mini" controls preload="none" src="03_overlap/separated_segments/' + fn + '"></audio> <span style="font-size:10px;color:#888">' + fn + '</span></div>');
    });
  }
  return rows.join("");
}

function renderTable(filterText, filterSpk, filterFlag) {
  tbody.innerHTML = "";
  const ft = (filterText || "").trim().toLowerCase();
  let visible = 0;
  SEGMENTS.forEach(s => {
    const d = s.end - s.start;
    const altsDiffer = (
      (s.text_whisper && s.text_whisper.trim().toLowerCase() !== (s.text || "").trim().toLowerCase()) ||
      (s.text_phowhisper && s.text_phowhisper.trim().toLowerCase() !== (s.text || "").trim().toLowerCase()) ||
      (s.text_chunkformer && s.text_chunkformer.trim().toLowerCase() !== (s.text || "").trim().toLowerCase())
    );
    if (ft) {
      const blob = [s.text, s.text_whisper, s.text_phowhisper, s.text_chunkformer].join(" ").toLowerCase();
      if (!blob.includes(ft)) return;
    }
    if (filterSpk && s.speaker !== filterSpk) return;
    if (filterFlag === "sepreformer" && !s.sepreformer) return;
    if (filterFlag === "is_separated" && !s.is_separated) return;
    if (filterFlag === "demucs" && !s.demucs) return;
    if (filterFlag === "short" && d >= 1.0) return;
    if (filterFlag === "qa" && (!s.asr_quality_actions || !s.asr_quality_actions.length)) return;
    if (filterFlag === "alts_disagree" && !altsDiffer) return;
    visible++;
    const tr = document.createElement("tr");
    const c = COLORS[s.speaker] || "#888";
    tr.innerHTML =
      '<td>' + s.index + '</td>' +
      '<td class="seg-time">' + fmtRange(s.start, s.end) + '<div class="seg-dur">' + d.toFixed(2) + 's</div>' +
        '<button class="jump-btn" data-t="' + s.start + '" data-i="' + s._i + '">▶ in full</button></td>' +
      '<td><span class="speaker-badge" style="background:' + c + '">' + s.speaker.replace("SPEAKER_", "") + '</span></td>' +
      '<td><audio class="mini" controls preload="none" src="05_export/final/' + s.audio_file + '"></audio></td>' +
      '<td class="seg-text">' + escapeHTML(s.text) + altsHTML(s) +
        '<details><summary>details</summary><div class="details-box">' + detailsHTML(s) + '</div></details></td>' +
      '<td><div class="flags">' + flagsHTML(s) + '</div></td>';
    tbody.appendChild(tr);
  });
  vcount.textContent = visible + " / 138";
  // wire jump buttons
  tbody.querySelectorAll(".jump-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      const t = parseFloat(btn.dataset.t);
      const i = parseInt(btn.dataset.i);
      jumpFull(t, SEGMENTS[i]);
    });
  });
}

searchEl.addEventListener("input", () => renderTable(searchEl.value, fspk.value, fflag.value));
fspk.addEventListener("change", () => renderTable(searchEl.value, fspk.value, fflag.value));
fflag.addEventListener("change", () => renderTable(searchEl.value, fspk.value, fflag.value));

renderTable("", "", "");
